"""Explicit editorial review of the final 48 pending CTB library units."""
import copy,json,sys
from pathlib import Path
p=Path(sys.argv[1]);old=json.loads((p/'batch-07-existing.json').read_text());expected={r['unit']['unit_key']:r for r in old};rows={}
CTB='https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm'
CP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm'
R1025='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/resolucao10252026c.pdf'
R1031='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/resolucao10312026.pdf'
R996='https://www.gov.br/transportes/pt-br/assuntos/transito/conteudo-contran/resolucoes/Resolucao9962023.pdf'
STF305='https://noticias.stf.jus.br/postsnoticias/stf-reafirma-validade-de-dispositivo-que-tipifica-como-crime-a-fuga-do-local-de-acidente-de-transito/'
STJ575='https://processo.stj.jus.br/SCON/sumstj/doc.jsp?b=SUMU&i=1&l=10&operador=AND&ordenacao=-%40NUM&p=false&sumula=575+INPATH%28NUM%29'
def add(n,case,variation,q1,q2,term,meaning,**patch):
 key=n if n=='anexo-1' else 'art-'+str(n);e=copy.deepcopy(expected[key]['explanation']);data={k:e[k] for k in ['simples','pontos','atencao','exemplo','prova','termos','remissoes']}
 data.update(exemplo=case+' Variação: '+variation,prova=[q1,q2],termos=[dict(termo=term,significado=meaning)])
 data['pontos']+=patch.pop('extra_points',[]);data['atencao']+=patch.pop('notes',[]);data['remissoes']=list(dict.fromkeys([CTB,*data['remissoes'],*patch.pop('sources',[])]));data.update(patch);rows[key]=data
add(296,'Réu pratica novo crime do CTB após condenação criminal transitada em julgado, preenchidos os requisitos de reincidência. Resposta: a suspensão do art. 296 é obrigatória, sem prejuízo das demais sanções.', 'Duas multas administrativas ou dois inquéritos não equivalem a reincidência penal.', 'Duas autuações já tornam o motorista reincidente penal? Não. É preciso condenação criminal anterior definitiva e requisitos dos arts. 63 e 64 do CP, não simples repetição administrativa.', 'O juiz pode dispensar livremente a suspensão quando configurada a hipótese? Não. O artigo usa APLICARÁ, sem substituir a análise prévia da reincidência legal.', 'Reincidência penal','Novo crime após condenação definitiva anterior, observados os requisitos e limites legais.',notes=['Integrar CP 63/64: não tratar toda condenação antiga como reincidência eterna nem denúncia como condenação.'],sources=[CP])
add(297,'Prejuízo material demonstrado é R$ 2.000. Resposta: multa reparatória não pode exceder esse valor e é depositada judicialmente em favor da vítima/sucessores.', 'Esse pagamento será descontado na indenização civil; não somar duas vezes o mesmo valor reparado.', 'Pode fixar R$ 3.000 de multa reparatória para prejuízo comprovado de R$ 2.000? Não. O §1º limita ao prejuízo demonstrado; não é licença para arbitramento superior.', 'O depósito elimina toda discussão sobre saldo indenizatório civil? Não. O §3º determina desconto do valor pago, distinto de extinguir todo dano civil eventualmente comprovado.', 'Multa reparatória','Pagamento judicial em favor da vítima/sucessores, com teto no prejuízo material comprovado.',notes=['Não confundir multa administrativa ao órgão de trânsito, pena de multa comum e reparação à vítima. Remissões CP 49, §1º, e 50–52 exigem integração atual.'],sources=[CP])
add(298,'Crime de trânsito é cometido com placas falsas e a circunstância não constitui elemento ou causa especial já valorada. Resposta: examinar agravante do inciso II.', 'No homicídio culposo sem habilitação, o mesmo fato já tem majorante específica do 302, §1º, I; não valorar novamente como agravante genérica.', 'A palavra sempre permite punir duas vezes pelo mesmo fato? Não. Integrar CP 61, caput, e vedação de bis in idem quando a circunstância já constitui ou qualifica o crime ou tem aumento específico.', 'A existência de passageiro único já corresponde ao inciso I de duas ou mais pessoas? Não. Há recortes distintos: duas ou mais pessoas OU grande risco de grave dano patrimonial a terceiros.', 'Bis in idem','Dupla valoração punitiva indevida do mesmo fundamento, distinta de circunstâncias independentes.',simples='O art. 298 enumera sete agravantes dos crimes de trânsito, incluindo risco a duas ou mais pessoas ou grande risco de grave dano patrimonial, placas irregulares, habilitação, cuidados profissionais, adulteração de segurança e faixa de pedestres. A expressão sempre não autoriza dupla valoração: integrar CP 61 e causas específicas, como 302, §1º. Parágrafo vetado não cria regra atual.',atencao=['Não ensinar aplicação automática cumulativa de agravante e majorante pelo mesmo fato.','Inciso V inclui cuidados especiais com PASSAGEIROS OU CARGA; a majorante do 302, §1º, IV, tem recorte próprio de transporte de passageiros.'],sources=[CP])
add(301,'Condutor presta pronto e integral socorro à vítima de sinistro de trânsito. Resposta: o artigo impede prisão em flagrante e exigência de fiança no seu recorte.', 'Socorrer não torna o homicídio culposo inexistente nem dispensa investigação, responsabilidade civil ou eventual medida judicial cabível.', 'O socorro extingue todo crime e todo procedimento? Não. A consequência descrita é não impor flagrante nem exigir fiança, sem imunidade penal universal.', 'Um telefonema tardio e abandono da vítima bastam sempre? Não. O artigo exige PRONTO E INTEGRAL socorro, a ser aferido concretamente, não mero ato simbólico.', 'Socorro pronto e integral','Condição específica do art. 301, distinta de absolvição ou de imunidade geral.',notes=['Não estender automaticamente a benefício para todo delito doloso ou flagrante independente.'])
add(302,'Motorista causa morte por imprudência, sem influência de substância. Resposta: homicídio CULPOSO na direção, detenção de dois a quatro anos e pena relativa à habilitação.', 'No §3º, culpa e influência de álcool/substância levam a reclusão de cinco a oito anos; álcool não prova sozinho dolo eventual.', 'Todo condutor alcoolizado que mata responde automaticamente por homicídio doloso? Não. Dolo exige demonstração própria; o CTB prevê homicídio culposo qualificado no §3º.', 'A majorante profissional alcança indistintamente qualquer caminhoneiro só por exercer profissão? Não. O §1º, IV, descreve exercício profissional conduzindo veículo de transporte de PASSAGEIROS; não copiar o rol mais amplo do 298.', 'Culpa e dolo','Imprudência/negligência/imperícia e dolo são fundamentos distintos, não definidos apenas pela ingestão de álcool.',atencao=['Lei 13.546/2017 incluiu §3º; não chamar genericamente Lei Seca sem identificar alteração.','§2º e inciso V revogados não são alternativas atuais de pena.','Majorantes de um terço à metade têm hipóteses expressas; não duplicar fundamento com 298.','O enquadramento depende de nexo, conduta, culpa/dolo e prova. Não automatizar inferência de dolo por álcool ou velocidade.'],sources=[CP],extra_points=['§3º: RECLUSÃO 5–8 anos, não detenção; integrar a regra especial do art. 312-B.'])
add(303,'Motorista com capacidade psicomotora alterada por álcool causa lesão grave culposa. Resposta: §2º, reclusão de dois a cinco anos, sem prejuízo das outras penas.', 'Lesão leve mesmo com álcool não satisfaz sozinha o §2º; examinar regime próprio e exceções processuais do 291, sem inventar pena qualificada.', 'Qualquer lesão de motorista que bebeu implica reclusão de dois a cinco anos? Não. Exige alteração psicomotora por substância E lesão grave ou gravíssima, além da culpa e demais elementos.', 'O §1º tem majorantes totalmente diferentes das do homicídio? Não. Remete às hipóteses do 302, §1º, com aumento de um terço à metade.', 'Requisitos cumulativos','Elementos que precisam coexistir para a qualificadora, não alternativas independentes.',atencao=['Lei 13.546/2017: alteração psicomotora + lesão grave/gravíssima. Não equiparar influência de álcool isolada à prova de todos os requisitos.','Integre art. 291 para institutos processuais e 312-B para substituição; não declarar todas as lesões leves automaticamente sujeitas a transação.'])
add(304,'Condutor tem justa causa que impede socorro direto, mas pode pedir auxílio público e não pede. Resposta: a omissão alternativa descrita pode configurar o artigo.', 'Se omissão já integra crime mais grave, observar subsidiariedade e evitar somar automaticamente 304 à majorante do 302 pela mesma omissão.', 'O socorro por terceiro sempre apaga a omissão do condutor? Não. O parágrafo expressamente conserva incidência mesmo quando a omissão é suprida por terceiros, observados os elementos do delito.', 'Impossibilidade justa de socorro direto autoriza abandonar sem pedir auxílio disponível? Não. O tipo prevê dever de solicitar auxílio da autoridade pública nessa hipótese.', 'Subsidiariedade','Aplicação se o fato não constituir elemento de crime mais grave, evitando duplicidade punitiva.',notes=['Parágrafo menciona morte instantânea/ferimentos leves; não dispensar exame de conduta e culpabilidade nem impor socorro fisicamente impossível.'])
add(305,'Condutor foge para evitar responsabilidade civil pelo sinistro. Resposta: finalidade de fuga à responsabilidade CIVIL OU PENAL integra o tipo, mesmo sem confissão exigida.', 'Afastar-se para buscar socorro ou por risco concreto não equivale por si à finalidade específica descrita; apurar circunstâncias.', 'STF considerou o artigo integralmente inconstitucional por não autoincriminação? Não. Tema 907, RE 971959, e ADC 35 reconheceram sua constitucionalidade; permanecer para identificação não equivale a confessar.', 'Sair do local já demonstra automaticamente finalidade criminosa? Não. A finalidade de fugir à responsabilidade deve ser aferida; deslocamento por causa diversa não pode ser equiparado sem análise.', 'Finalidade específica','Propósito de fugir à responsabilidade penal ou civil, distinto do simples movimento físico.',atencao=['STF reafirmou constitucionalidade na ADC 35, sessão encerrada em 9/10/2020, noticiada em 14/10/2020; Tema 907.','Não copiar antigo alerta de controvérsia sem registrar entendimento atual nem converter permanência em dever de confissão.'],sources=[STF305])
add(306,'Etilômetro apresenta medição realizada de 0,34 mg/L, no procedimento metrológico pertinente. Resposta: comparar valor considerado após erro admitido com o limiar penal; não usar leitura bruta como se fosse considerada.', 'Recusa isolada não prova o crime, mas o conjunto de sinais registrado e outras provas lícitas pode demonstrar alteração psicomotora, com direito à contraprova.', 'O limite textual 0,3 mg/L elimina a margem metrológica do aparelho? Não. Distinguir limiar legal e medição realizada; Resolução 1031 trabalha com erro admitido e 0,34 mg/L na medição para o recorte criminal.', 'Sem teste de sopro é impossível comprovar o crime? Não. O §2º admite exame, perícia, vídeo, testemunhas e demais meios lícitos, com contraprova; recusa isolada não substitui prova.', 'Medição realizada e considerada','Leitura do aparelho e resultado após erro metrológico são valores distintos.',atencao=['Não afirmar que leitura bruta de 0,30 mg/L sempre configura crime: aplicar margem e procedimento vigentes.','Resolução 1031/2026 revogou 432/2013; pré-teste indicativo não substitui teste definitivo. Conjunto de ao menos dois sinais registrado, não sinal único isolado como regra automática.','Alterações de fichas do Manual 985 só em 17/10/2026; não antecipar na conferência de 13/10.','Infração administrativa e crime têm elementos próprios; não transformar qualquer quantidade de álcool ou recusa em condenação penal.'],sources=[R1031])
add(307,'Condenado viola suspensão judicial de direção imposta no processo criminal. Resposta: examinar art. 307, com detenção de seis meses a um ano E multa e nova imposição de idêntico prazo.', 'Para suspensão administrativa, não presumir responsabilidade criminal só pela palavra suspensão: distinguir art. 162, II, art. 263 e interpretação judicial específica.', 'No exemplo de suspensão judicial, a nova imposição tem qualquer prazo escolhido livremente pelo artigo? Não. O tipo prevê adicional de IDÊNTICO PRAZO de suspensão/proibição, com os demais requisitos.', 'A omissão de entrega do documento dispensa o marco da intimação do 293? Não. O parágrafo remete ao 293, §1º: prazo de 48 horas após intimação pertinente, não ciência informal sem procedimento.', 'Suspensão judicial','Medida imposta no processo penal, cuja violação deve ser distinguida da suspensão administrativa.',atencao=['Não deduzir incidência penal universal de toda suspensão administrativa a partir da literalidade; confronto jurisprudencial específico necessário.','Não certificada neste lote a íntegra da jurisprudência sobre suspensão administrativa: pesquisa oficial não retornou acórdão identificável. Exemplos limitados à suspensão judicial e ao marco textual da entrega.','Responsabilidade penal não é automática: examinar decisão válida, ciência, conduta e elementos subjetivos.'])
add(308,'Corrida não autorizada em via pública gera risco à incolumidade. Resposta: examinar caput, detenção de seis meses a três anos, multa e consequência à habilitação.', 'Competição autorizada em circuito fechado não se equipara automaticamente ao caput. Morte não querida nem assumida tem §2º; dolo exige enquadramento próprio.', 'A morte do §2º pode ser desejada ou ter risco assumido pelo agente? Não. A qualificadora pressupõe que ele NÃO quis resultado NEM assumiu risco; não copiar como tipo para todo homicídio doloso.', 'Qualquer manobra exibida em qualquer espaço é automaticamente art. 308? Não. O tipo exige direção automotora, via pública, ausência de autorização e risco à incolumidade, no recorte descrito.', 'Resultado não doloso','Qualificadora por resultado que não foi querido nem teve risco assumido, distinta de dolo.',notes=['Lesão GRAVE: reclusão 3–6; morte: reclusão 5–10, sem prejuízo das outras penas; não trocar faixas.'])
add(309,'Pessoa sem habilitação dirige em via pública criando perigo de dano comprovado. Resposta: tipo penal de perigo concreto, distinto da mera falta documental.', 'Sem demonstrar perigo de dano do tipo, não concluir crime do 309 apenas porque existe infração administrativa; entregar direção pelo 310 tem entendimento próprio.', 'A mera ausência de CNH elimina necessidade de provar perigo no 309? Não. O artigo exige GERANDO PERIGO DE DANO; sanção administrativa tem pressupostos próprios.', 'O 310 deve receber por analogia todos os elementos do 309? Não. São condutas e regimes distintos; Súmula 575/STJ trata da entrega/permissão sem exigir perigo concreto.', 'Perigo concreto','Perigo de dano exigido no tipo, distinto da presunção suficiente em crime de perigo abstrato.',notes=['Via pública e veículo automotor integram o 309; não confundir CNH vencida ou documento não portado com todas as hipóteses penais.'],sources=[STJ575])
add(310,'Proprietário entrega conscientemente a direção a pessoa não habilitada. Resposta: Súmula 575/STJ dispensa lesão ou perigo de dano concreto para o art. 310.', 'Dirigir sem habilitação é conduta do 309, com perigo de dano; não copiar sua exigência para aquele que permite/confia/entrega.', 'Para quem entrega a direção, é indispensável acidente com vítima? Não. Súmula 575: crime independentemente de lesão ou perigo de dano concreto, sem dispensar conduta e demais elementos.', 'A deficiência ou diagnóstico tornam toda entrega criminosa? Não. O recorte de saúde exige falta de condições de conduzir com segurança; não presumir incapacidade pela deficiência em si.', 'Perigo abstrato','No recorte da Súmula 575, dispensa prova de perigo concreto, não dispensa os demais elementos do crime.',notes=['Súmula 575/STJ julgada em 22/6/2016, DJe 27/6/2016; texto oficial consultado em 13/10/2026.','Não presumir ciência ou dolo por simples propriedade do veículo; analisar o ato de permitir, confiar ou entregar.'],sources=[STJ575])
add(311,'Condutor passa diante de escola em velocidade incompatível e gera perigo concreto. Resposta: art. 311 exige contexto, incompatibilidade e perigo de dano.', 'Ultrapassar limite numérico do 218 não satisfaz automaticamente todos os elementos do 311; velocidade formalmente permitida também não garante segurança concreta.', 'Só radar acima da placa é suficiente para provar todos os elementos do crime? Não. O tipo exige velocidade incompatível nos contextos enumerados e perigo de dano, não mero percentual de excesso.', 'A ausência de vítima lesionada impede o tipo? Não. O artigo exige perigo de dano, distinto de lesão consumada, sempre com prova do recorte concreto.', 'Velocidade incompatível','Inadequação à segurança nas condições concretas, distinta de simples comparação numérica com a placa.',notes=['Integre art. 220 para infração administrativa; não converter todo excesso de velocidade em crime.'])
add(312,'Após sinistro com vítima, condutor altera artificialmente posição de objeto para enganar perícia, antes de aberto inquérito. Resposta: parágrafo permite incidência mesmo antes do procedimento.', 'Retirar veículo para salvar vítima, sem finalidade de induzir autoridade a erro, não se equipara automaticamente à fraude.', 'Toda mudança na cena para socorrer é fraude do 312? Não. Exige inovação artificiosa e finalidade de induzir a erro policial, perito ou juiz; socorro não prova esse propósito.', 'A inexistência de inquérito já instaurado impede sempre o crime? Não. O parágrafo alcança inovação antes do início dos procedimentos enumerados, no contexto de sinistro com vítima.', 'Inovação artificiosa','Alteração com propósito de enganar os destinatários legais, distinta de qualquer movimentação legítima.',notes=['Não omitir COM VÍTIMA e finalidade específica; preservar segurança/socorro e análise da prova.'])
add('312-a','Juiz admite substituição cabível para crime do capítulo. Resposta: o 312-A direciona prestação de serviços a resgate, atendimento ou recuperação de vítimas.', 'O artigo não torna cabível substituição em todo caso: integrar requisitos CP 44 e exceção do 312-B antes de escolher atividade.', 'Basta o artigo existir para converter automaticamente qualquer pena do CTB? Não. Ele regula a atividade quando houver substituição cabível; os requisitos e a exceção do 312-B continuam necessários.', 'A atividade pode ser livremente escolhida sem vínculo com vítimas de trânsito? Não. O rol e inciso IV vinculam serviço a resgate, atendimento e recuperação de vítimas de sinistros.', 'Substituição e atividade','Cabimento da alternativa e modalidade de seu cumprimento são etapas distintas.',atencao=['Lei 13.281/2016 inseriu 312-A; Lei 14.599/2023 atualizou terminologia. Não confundir substituição com suspensão condicional da pena ou do processo.'],sources=[CP])
add('312-b','Homicídio culposo do 302, §3º, é invocado como substituível só porque crime culposo admite regra geral do CP 44, I. Resposta: o 312-B excepciona essa via nos dois tipos expressos.', 'O dispositivo não menciona todos os crimes do CTB nem equivale sozinho a proibir universalmente ANPP, transação ou sursis: cada instituto exige exame próprio.', 'A regra qualquer que seja a pena se culposo do CP 44, I, pode ser aplicada sem ressalva ao 302, §3º? Não. O 312-B afasta esse inciso para 302, §3º, e 303, §2º; integrar a regra especial.', 'O 312-B afasta expressamente todos os benefícios processuais de todo crime de trânsito? Não. Sua remissão é específica ao inciso I do caput do CP 44 e aos dois tipos enumerados.', 'Exceção à regra geral','Restrição especial aos dois delitos expressos, distinta de proibição genérica de todo benefício.',simples='O art. 312-B, incluído pela Lei 14.071/2020, excepciona o inciso I do caput do CP 44 nos crimes do 302, §3º, e 303, §2º. Não aplicar sem ressalva a regra geral de substituição de crimes culposos qualquer que seja a pena. Não confundir substituição por restritivas com suspensão condicional da pena/processo ou ANPP, cujos requisitos são próprios.',pontos=['Recorte: 302, §3º, e 303, §2º, não todos os crimes de trânsito.','Remissão: CP 44, caput, I, incluindo regra geral para crimes culposos.','Lei 14.071/2020 teve vacância própria de 180 dias, já encerrada na conferência de 2026.'],atencao=['A explicação antiga resumia CP 44, I, só como crimes com violência; omitia sua cláusula para culposos. Texto atual integrado.','Não gerar exercício que estenda a remissão a todo benefício ou a todo delito do CTB.'],sources=[CP])
add(313,'Questão histórica pergunta prazo inicial de nomeação dos membros do Contran. Resposta: sessenta dias DA PUBLICAÇÃO do CTB.', 'A nomeação em 2026 não inaugura outro prazo original de 1997 nem permite ignorar composição atual do art. 10.', 'O prazo de sessenta dias renova a cada atualização do Código? Não. O marco textual é a publicação original; regra de implantação histórica, não janela anual atual.', 'O artigo fixa prazo de vigência geral do CTB? Não. Nomeação inicial e vacância geral do art. 340 são prazos diferentes.', 'Implantação inicial','Obrigação referida à publicação original, sem reinício em atualizações posteriores.',notes=['Trecho histórico de implantação: exemplos explicitamente históricos; não exigir novo cumprimento do prazo original em 2026.'])
add(314,'No estudo histórico da implantação, o Contran recebeu 240 dias da publicação para resoluções e revisão do acervo anterior. Resposta: prioridade à segurança e pedestres.', 'Resolução antiga só pode ser usada hoje após confronto com normas posteriores e revogações, não apenas porque não conflitava em 1997.', 'Toda resolução anterior continua hoje vigente pelo parágrafo? Não. A manutenção era na parte compatível; revogações/substituições posteriores também precisam ser verificadas.', 'A atualização de sinistro em 2023 reiniciou o prazo de 240 dias da publicação original? Não. O marco continua histórico; mudança terminológica não cria novo prazo de implantação.', 'Compatibilidade e sucessão','Confronto com CTB e normas posteriores antes de tratar ato anterior como atual.',notes=['Não certificar vigência atual de todo acervo do Contran por essa regra transitória.'])
add(315,'Questão sobre implantação distingue proposta do Contran e estabelecimento do currículo pelo MEC em 240 dias da publicação. Resposta: competências distintas.', 'Atualização de redação em 2023 não concede automaticamente nova janela inicial nem prova que todo currículo atual foi auditado.', 'É o Contran sozinho quem estabelece o currículo desse artigo? Não. O MEC atua mediante proposta do Contran, com o marco histórico de publicação do CTB.', 'O prazo de 240 dias autoriza adiar hoje toda educação de trânsito por mais oito meses? Não. Trata de implantação original, distinto das obrigações educacionais atuais.', 'Proposta e decisão curricular','Contran propõe; MEC estabelece no recorte normativo, sem confundir os órgãos.',notes=['Leitura histórica do prazo; integrar educação atual do art. 76, sem alegar conferência integral de atos curriculares.'])
add(316,'Estudo histórico mostra que o prazo de notificação teve início diferido por 240 dias da publicação original. Resposta: essa transição já não suspende notificações atuais.', 'Em 2026, expedição do 281 e regimes especiais vigentes devem ser examinados sem reeditar a carência de 1997.', 'Cada alteração do 281 reinicia os 240 dias do 316? Não. O marco do artigo é a publicação original desta lei, não toda alteração posterior.', 'A remissão antiga parágrafo único dispensa consultar numeração atual do 281? Não. A estrutura foi modificada; integrar dispositivo atual e sua transição específica sem transformar remissão antiga em regra nova.', 'Vigência diferida histórica','Adiamento ligado ao início do CTB, distinto dos prazos atuais de autuação.',notes=['Texto residual remete a parágrafo único do 281; atual estrutura tem parágrafos. Não suspender multas atuais com base na transição original.'])
add(317,'Implantação do CTB concedeu até um ano para adequação da identificação de escolares/aprendizagem. Resposta: prazo histórico, não nova tolerância a partir de cada fiscalização.', 'Veículo adquirido em 2026 deve atender ao regime atual; o 317 não concede automaticamente um ano sem faixa ou identificação exigível.', 'Todo escolar irregular hoje recebe um ano automático para se adequar por esse artigo? Não. É regra histórica de implantação; não dispensa obrigações atuais dos 136/154.', 'O teto histórico era de dois anos? Não. O artigo estabeleceu ATÉ UM ANO, sem prorrogação universal para cada veículo.', 'Adaptação histórica','Prazo inicial já superado, distinto de autorização atual para operar irregularmente.',notes=['Não certificar que toda adaptação foi efetivamente cumprida nem abrir carência atual com prazo original.'])
add(319,'Aluno lê referência ao art. 92 do regulamento de 1968. Resposta: a manutenção dependia da ausência de novas normas, não preservação eterna de todo decreto.', 'Normas atuais de segurança e identificação exigem confronto próprio; não usar a remissão antiga para afastar resolução posterior válida.', 'O dispositivo torna íntegro regulamento de 1968 permanentemente vigente? Não. Refere-se ao art. 92 e condição enquanto não baixadas novas normas, com confronto de sucessão normativa.', 'Uma questão atual pode copiar regra antiga sem conferir substituição? Não. A remissão de transição não substitui validação das normas atuais aplicáveis.', 'Manutenção condicionada','Ponte transitória até novas normas, distinta de repristinação do regulamento inteiro.',atencao=['Não certificada neste lote a cadeia completa de todos os atos sucessores da remissão de 1968. Exercícios não ensinam especificação antiga como regra atual.'])
add('319-a','Contran divulga novo valor de multa. Resposta: correção possível dentro da variação do IPCA anterior e divulgação com no mínimo noventa dias.', 'A inflação não reajusta automaticamente toda multa sem ato e antecedência; não recalcular multas atuais só aplicando IPCA por conta própria.', 'A palavra poderão dispensa ato e divulgação para corrigir automaticamente? Não. A autorização é condicionada ao limite e divulgação; não cria atualização automática informal.', 'Sessenta dias de antecedência bastam ao parágrafo? Não. O mínimo textual é NOVENTA dias antes da aplicação dos novos valores.', 'Correção condicionada','Possibilidade regulada pelo índice e pela antecedência, distinta de reajuste automático.',notes=['Distinguir valores vigentes do art. 258 de autorização para futura correção; não inventar ato de reajuste não consultado.'])
add(320,'Candidato inscrito no CadÚnico é analisado em programa de custeio da habilitação. Resposta: §§4º/5º incluem taxas/despesas de formação e documento, com definição legal de baixa renda.', 'Inscrição no CadÚnico não certifica por si vaga imediata em qualquer programa local nem gratuidade ilimitada sem procedimento.', 'A inclusão no CadÚnico está fora da definição legal dessa baixa renda? Não. O §5º a utiliza para caracterizar o candidato no regime do §4º, sem dispensar aplicação do programa pertinente.', 'Toda arrecadação de multa pode custear livremente qualquer despesa municipal? Não. O caput estabelece destinações EXCLUSIVAS e §1º cinco por cento ao fundo nacional, com transparência anual.', 'Destinação vinculada','Receita com finalidades expressas, distinta de recurso livre do orçamento.',extra_points=['Lei 15.153/2025: custeio inclui TAXAS e demais despesas de formação/concessão; candidato definido por inclusão no CadÚnico.','§3º: limite da recomposição de perdas de pedágio vinculado à arrecadação do 209-A, ressalvado regulamento.'],notes=['Não prometer vaga automática, gratuidade de toda despesa futura ou implantação uniforme de programa em todo ente.','Fundo do §1º, depósito MENSAL; divulgação de receita/destinação ANUAL, não trocar periodicidades.'],sources=['https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15153.htm'])
add('320-a','Órgãos do SNT pactuam integração de fiscalização e compartilhamento da receita. Resposta: artigo permite integração, mas finalidade legal permanece vinculada.', 'Compartilhar não libera aplicação em despesas alheias às finalidades do 320 nem confere toda competência indistintamente a qualquer órgão.', 'A receita compartilhada perde o vínculo às finalidades do 320? Não. A integração não elimina destinação legal; não vira receita livre por mudar o órgão destinatário.', 'O artigo torna obrigatória toda divisão de receita em partes iguais? Não. Diz PODERÃO integrar-se, inclusive compartilhar; não fixa divisão universal de cinquenta por cento.', 'Integração de fiscalização','Cooperação possível no SNT, sem divisão fixa de receita nem competência ilimitada.',notes=['Não inventar percentuais, convênio concreto ou poder fora da circunscrição sem ato pertinente.'])
add(323,'Questão histórica sobre metodologia de pesagem menciona 180 dias e multa provisória de vinte UFIR por 200 kg/fração. Resposta: regime inicial, não tabela atual.', 'Cálculo de excesso em 2026 exige art. 231 atual e regulamentação pertinente, sem reeditar fórmula provisória ou parágrafo revogado em 2023.', 'Pode usar os vinte UFIR como tabela atual de todo excesso? Não. É previsão provisória do período de implantação, distinta do regime atual; não converter UFIR em reais por conta própria.', 'O parágrafo único revogado em 2023 gera hoje tolerância adicional? Não. Trecho revogado não pode ser tratado como regra ativa; integrar texto e regulamentação vigentes.', 'Fórmula provisória','Cálculo histórico delimitado à transição, não tarifa atual de multa.',notes=['Não certificada aqui toda metodologia metrológica de pesagem; exemplos apenas históricos, com ressalva explícita.'])
add(325,'Detran armazena documentos digitalmente com requisitos de autenticidade e sistema certificado conforme ICP-Brasil. Resposta: mínimo de cinco anos e possível dispensa de guarda física nas condições legais.', 'Fotografia informal sem integridade ou segurança não satisfaz automaticamente todos os requisitos de armazenamento digital.', 'O prazo mínimo de cinco anos obriga eliminar tudo exatamente ao final? Não. É mínimo de conservação; eliminação exige regime aplicável, não destruição automática pelo aniversário.', 'Digitalizar por qualquer meio dispensa sempre o original físico? Não. O §1º condiciona validade e dispensa a autenticidade/fidedignidade/confiabilidade/segurança; §3º exige sistema certificado no recorte.', 'Conservação mínima','Limite inferior de guarda, distinto de prazo máximo ou autorização automática de descarte.',extra_points=['§3º: sistema certificado digitalmente conforme autenticidade, integridade, validade jurídica e interoperabilidade da ICP-Brasil.'],notes=['Não certificar conformidade de qualquer sistema concreto apenas porque seus arquivos são eletrônicos.'])
add(326,'Calendário educacional marca Semana Nacional de Trânsito entre 18 e 25 de setembro. Resposta: período anual expresso.', 'Campanhas em julho para motociclistas não alteram setembro; têm previsão própria no 326-B.', 'O dia 27 de julho substituiu a Semana Nacional de Trânsito? Não. São previsões distintas: 326 em setembro e 326-B em julho, ambas com suas finalidades.', 'O período do 326 ocorre só a cada quatro anos? Não. O artigo determina comemoração ANUAL entre 18 e 25 de setembro.', 'Calendários distintos','Datas educativas diferentes coexistem sem revogar umas às outras.',notes=['Não misturar Semana Nacional de Trânsito, semana de prevenção com motociclistas e memória das vítimas.'])
add('326-a','Índice de mortes de 2020 usado como referência é 20 por grupo de habitantes. Resposta: objetivo mínimo ao fim de 2030 é reduzir pela metade, a 10 ou menos, com metodologia oficial.', 'Não substituir por reduzir pela metade simples número absoluto sem ajustar grupo de habitantes, nem usar 2018 como base atual.', 'A base atual da meta é 2018 por ser ano de inclusão do artigo? Não. Redação de 2023 usa índice de 2020 e objetivo ao final de 2030; data original da alteração não é base estatística.', 'Todos os dados e metas são divulgados no mesmo dia de agosto? Não. Propostas até 1º/8; índices até 30/4; divulgação de metas e desempenho em setembro, conforme parágrafos próprios.', 'Índice e número absoluto','Relação por grupo de habitantes, distinta da contagem absoluta isolada de mortes.',extra_points=['Metas: Contran mediante propostas de Cetran/Contrandife/PRF; consulta OU audiência pública antes da proposta.','Propostas até 1º de agosto; índices até 30 de abril; metas/desempenho na Semana de setembro.','Órgãos estaduais/DF consolidam dados da circunscrição; órgão máximo executivo federal calcula índices com os participantes legais.','§14: duas classificações, do ano e da evolução, além do relatório do objetivo geral.'],notes=['Exemplo numérico apenas pedagógico; não é dado real de mortalidade nem certificação de atingimento da meta.','Não certificada integralmente neste lote a metodologia técnica do Pnatrans ou todas suas resoluções.'])
add('326-b','Campanha de prevenção com motociclistas ocorre na semana que contém 27 de julho. Resposta: o dia 27 é o Dia Nacional do Motociclista.', 'A semana não recebe intervalo fixo universal 20–27 de julho do texto; ela é definida pela semana que compreender o dia.', 'O artigo fixa literalmente início no dia 20 e fim no dia 27? Não. Prevê semana que COMPREENDER 27 de julho, sem esse intervalo numérico fixo.', 'É a mesma comemoração da semana de setembro do 326? Não. A previsão específica de motociclistas foi incluída pela Lei 15.006/2024 e possui calendário próprio.', 'Semana que compreender','Referência ao dia contido na semana, distinta de intervalo de datas inventado.',notes=['Não equiparar data original da Lei 15.006/2024 à data de conferência ou à inclusão recente do 326-C.'])
add('326-c','Em 2026, o terceiro domingo de novembro é 15/11. Resposta: aplica-se o critério anual do terceiro domingo, não data fixa permanente do mês.', 'Em outro ano, o dia numérico pode mudar; permanece TERCEIRO DOMINGO de novembro.', 'A comemoração ocorre sempre em 15 de novembro? Não. 15/11 é o resultado do calendário de 2026; a regra legal é o terceiro domingo do mês a cada ano.', 'A Lei 15.452 começou a vigorar apenas no aniversário de junho de 2027? Não. O art. 2º prevê vigência na publicação; assinada em 30/6/2026 e publicada em 1º/7/2026.', 'Data móvel anual','Dia definido pela posição do domingo no mês, distinto de dia numérico fixo.',atencao=['Lei 15.452 de 30/6/2026, DOU de 1º/7/2026, vigência na publicação; conferência em 13/10/2026 são três marcos diferentes.'],sources=['https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15452.htm'])
add(327,'Fabricante pretende licenciar veículo fora de peso/dimensões sem enquadramento em ressalva regulamentar. Resposta: observar limites e norma específica válida.', 'A ressalva de regulamentação não permite excesso por simples vontade do fabricante ou dispensa geral de autorização pertinente.', 'O artigo admite veículo fora dos limites por mera declaração privada? Não. A ressalva é para os regulamentados pelo Contran, com requisitos pertinentes, não autocertificação irrestrita.', 'Estar entre disposições finais torna a obrigação sem efeito em todo caso atual? Não. O artigo enuncia obrigação a partir da publicação, distinta de prazos iniciais já encerrados.', 'Obrigação e ressalva','Limites legais com exceção regulada, sem autorização privada universal.',notes=['Não tratar todo capítulo final como revogado ou de eficácia esgotada; distinguir cada dispositivo.'])
add(328,'Veículo não reclamado atinge sessenta dias do recolhimento. Resposta: examinar avaliação/leilão com requisitos e notificações; preparar após trinta não significa leiloar no dia trinta.', 'Sucata não volta à circulação; veículo conservado sem arrematação duas vezes passa ao regime de sucata. Não confundir categorias ou fases.', 'No leilão seguinte qualquer lance inferior a cinquenta por cento pode vencer pelo §2º? Não. O maior lance deve respeitar piso de CINQUENTA POR CENTO do avaliado na hipótese expressa.', 'A desvinculação dos débitos extingue toda dívida do antigo proprietário? Não. §9º preserva cobrança contra ele e §11 revincula se reaver o bem; não transferir automaticamente débitos antigos ao comprador.', 'Preparação e alienação','Etapas com prazos e requisitos próprios, distintas do simples tempo de depósito.',simples='Veículo recolhido e não reclamado em sessenta dias pode seguir avaliação/leilão, preferencialmente eletrônico, observados procedimento e notificações. Preparação após trinta dias não antecipa o leilão. Há categorias conservado/sucata; segundo leilão tem piso de cinquenta por cento da avaliação. Sucata não retorna à circulação. Destinação da receita, desvinculação de débitos, saldo ao antigo proprietário e restrições têm regras próprias. Integrar Resolução 1025/2026; não confundir recolhimento com pena autônoma de apreensão revogada em 2016.',pontos=['60 dias do recolhimento; preparação depois de 30 e edital, não leilão antecipado.','Segundo leilão: maior lance com piso de 50% do avaliado; conservado não arrematado duas vezes: sucata.','Despesas de depósito limitadas a seis meses; não é período mínimo obrigatório de custódia.','Custos do leilão primeiro; remanescentes na ordem dos incisos I–VI do §6º.','Saldo após quitar débitos: notificar até 30 dias do leilão; levantamento em cinco anos; após, fundo nacional.','Restrição judicial/policial: comunicação e regime §§14–18; não dispensar análise por simples leitura do caput.','Reciclagem dos §§16–18 não autoriza vender sucata como veículo circulável nem aproveitar livremente peças no §17.'],atencao=['O §12 remete historicamente ao parágrafo único do 320: consultar atual §1º, não criar fundo diferente pela renumeração.','Resolução 1025/2026 revogou 623/2016; Sivec e SNE têm transições próprias. Não certificadas todas as especificações operacionais e anexos do leilão.','Débitos anteriores desvinculados do veículo não deixam automaticamente de ser cobrados do devedor.','Apreendido a qualquer título não restaura penalidade administrativa autônoma revogada.'],sources=[R1025])
add(329,'Condutor de escolar apresenta certidão prevista no artigo antes de exercer atividade. Resposta: crimes enumerados e renovação a cada cinco anos, no órgão da autorização.', 'Não substituir automaticamente cinco anos por periodicidade anual de outro documento nem ampliar o rol a todo crime sem fundamento.', 'A certidão é dispensada por o veículo escolar ter inspeção semestral? Não. São exigências distintas: art. 329 para condutor e art. 136 para veículo, com finalidades e prazos próprios.', 'O artigo determina condenação definitiva automática de quem consta em distribuição? Não. Exige certidão de distribuição no recorte, mas não transforma processo em condenação ou dispensa garantias constitucionais.', 'Certidão de distribuição','Documento sobre registros processuais no recorte legal, distinto de sentença condenatória.',notes=['Não declarar resolvida toda controvérsia constitucional ou modalidade de transporte; aplicar ao âmbito dos arts. 135/136 e procedimento pertinente.'])
add(330,'Oficina registra entrada e saída no próprio dia, com horas, e mantém acesso da autoridade ao registro. Resposta: requisitos não se limitam a anotar nome do veículo.', 'Sistema eletrônico pode substituir livros NA FORMA regulamentada, não qualquer planilha informal automaticamente válida.', 'A autoridade pode retirar os livros só por ter direito de acesso pelo §4º? Não. O parágrafo permite acesso mediante solicitação, mas proíbe retirá-los do estabelecimento nesse regime.', 'Falha de escrituração é sempre só infração leve sem outras consequências? Não. O §5º prevê multa de gravíssima para as condutas expressas, independentemente das demais cominações cabíveis.', 'Registro de movimento','Controle de entradas/saídas e demais campos exigidos, com acesso e forma regulados.',extra_points=['§3º: entrada/saída no MESMO DIA, assinaladas horas; §4º acesso sem retirada dos livros.','§5º: falta, atraso, fraude e recusa de exibição, multa de gravíssima.','§6º admite substituição eletrônica na forma regulamentada pelo Contran.'],notes=['Não presumir adequação regulamentar de software ou planilha concreta. Não confundir recolhimento para regularização e pena autônoma de apreensão do veículo revogada.'])
add(331,'Na transição de implantação, órgãos então existentes julgavam recursos até nomeação E posse dos novos colegiados. Resposta: continuidade condicionada, não competência eterna.', 'Em 2026, recursos seguem órgãos e composição atuais; não justificar julgamento por órgão antigo só com essa disposição.', 'Nomeação sem posse necessariamente satisfaz as duas condições expressas? Não. O texto fala nomeação E posse; distinguir os marcos de instalação no contexto histórico.', 'O dispositivo reinstala hoje órgãos antigos para todos os recursos? Não. É continuidade transitória de implantação, não regra de competência administrativa permanente.', 'Continuidade transitória','Evita vazio de julgamento na implantação, sem substituir o regime atual.',notes=['Não afirmar historicamente que todas as JARI inexistiam antes do CTB; o texto refere colegiados e órgãos então existentes.'])
add(332,'Membro do Cetran EM SERVIÇO solicita informação pertinente à missão. Resposta: órgão do SNT deve colaborar e atender prontamente a requisição legal.', 'O artigo não concede prerrogativa pessoal fora da missão nem dispensa proteção de dados, competência e legalidade.', 'O direito de facilitar a missão vale como privilégio pessoal fora de serviço? Não. A norma menciona membros EM SERVIÇO e facilidades para cumprimento de sua missão.', 'Órgãos do sistema podem recusar toda inspeção por ser conselho e não polícia? Não. O artigo prevê informações e inspeção da execução de serviços no recorte legal, com atendimento de requisições.', 'Colaboração institucional','Facilidades para missão funcional, distinta de privilégio pessoal ilimitado.',notes=['Não converter cooperação em competência penal ou acesso indiscriminado a toda informação sem recorte legal.'])
add(333,'Estudo histórico distingue 120 dias após nomeação para Contran editar normas e um ano após edição para adequação de órgãos existentes. Resposta: marcos diferentes.', 'Órgão municipal novo é acompanhado pelo Cetran; estadual/DF/União pelo Contran no §2º, não todos pelo Cetran.', 'O §2º manda Cetran acompanhar igualmente todo órgão federal? Não. Cetran para municipal; Contran para estadual, DF ou União, na redação do artigo.', 'O prazo de um ano é contado sempre da publicação original do CTB? Não. O §1º o conta após a EDIÇÃO DAS NORMAS, distinto do marco de 120 dias após nomeação.', 'Marcos de adequação','Nomeação, edição de normas e criação de órgão são fatos distintos para cada regra.',simples='O caput trata de 120 dias após nomeação dos membros do Contran para disposições dos arts. 91/92; §1º, um ano após edição das normas para órgãos existentes. São marcos históricos de implantação. §2º exige cumprimento das condições para órgãos novos: acompanhamento pelo Cetran quando municipal e Contran quando estadual, DF ou União, com integração ao SNT.',atencao=['Corrigida explicação antiga que atribuía genericamente todo acompanhamento ao Cetran.','Não reiniciar prazos históricos em cada atualização nem dispensar requisitos de integração atual.'])
add(334,'Lombada existente na implantação deveria ser homologada em um ano da publicação do CTB ou retirada. Resposta: prazo histórico, não tolerância para qualquer instalação atual.', 'Lombada criada em 2026 exige requisitos atuais; o prazo de 1997 não permite operar um ano sem homologação.', 'Toda lombada nova recebe um ano sem atender regra atual? Não. O texto trata das existentes na implantação e marco original; não cria carência para cada instalação nova.', 'A ausência de homologação histórica era indiferente segundo o artigo? Não. Previa retirada em caso contrário, distinguindo regularidade da simples presença física.', 'Homologação histórica','Adequação inicial das ondulações existentes, distinta de autorização para instalação atual irregular.',notes=['Não certificada neste item toda geometria ou regulamentação técnica de ondulações.'])
add(336,'Questão histórica menciona sinais do Anexo II até aprovação pelo Contran, com Câmara Temática e padrões internacionais. Resposta: previsão de transição, 360 dias da publicação.', 'Uma placa atual exige norma vigente específica; a menção ao Anexo II não prova que todo desenho antigo continua aprovado.', 'O prazo de 360 dias se reinicia a cada consulta do candidato? Não. O marco é publicação original da lei; a disposição trata da implantação da sinalização.', 'O artigo elimina manifestação técnica e padrões internacionais na aprovação descrita? Não. Explicita Câmara Temática e padrões, sem substituir consulta às normas atuais de sinalização.', 'Sinalização de transição','Regime inicial até aprovação pertinente, distinto de certificação de todas as placas atuais.',notes=['Não certificada a cadeia completa de todos os manuais/volumes de sinalização; não gerar exercício usando placa histórica como atual.'])
add(337,'Cetran recebe suporte técnico/financeiro dos Estados e Municípios que o compõem. Resposta: distinguir Contrandife, cujo suporte é do DF.', 'O artigo não fixa valor ou divisão de cinquenta por cento para cada ente nem aponta União como responsável universal.', 'O Contrandife recebe pelo artigo suporte obrigatório de todos os municípios brasileiros? Não. Seu destinatário de suporte é o Distrito Federal, com regra distinta dos Cetran.', 'O texto determina percentual igual de contribuição de cada município? Não. Identifica entes de suporte, sem percentual uniforme; não inventar rateio legal.', 'Suporte técnico e financeiro','Responsabilidade institucional dos entes indicados, distinta de fórmula de rateio inventada.')
add(338,'Importador comercializa veículo automotor e deve fornecer manual com normas, direção defensiva, primeiros socorros e anexos. Resposta: obrigação no ato da comercialização.', 'O texto inclui CICLOS, não apenas carros de passeio; não reduzir destinatários ou conteúdo a manual mecânico do fabricante.', 'Manual apenas de manutenção satisfaz necessariamente todo o artigo? Não. Ele enumera conteúdo de trânsito, infrações, penalidades, direção defensiva, primeiros socorros e anexos, além da função mecânica.', 'A obrigação textual exclui ciclos por não terem motor? Não. O artigo menciona veículos automotores de qualquer categoria E CICLOS; não restringir a carros.', 'Manual educativo','Conteúdo legal e de segurança exigido na comercialização, distinto do manual só mecânico.',notes=['Não inventar formato exclusivamente impresso/digital nem atestar adequação de manual comercial concreto sem conferência.'])
add('338-a','A partir de 1º/1/2024, aplicam-se competências dos órgãos dos arts. 21, XV, e 24, XXII. Resposta: tratar a regra anterior até 31/12/2023 como histórica.', 'A transferência dessas competências específicas não retira TODAS as competências estaduais do CTB.', 'O artigo elimina integralmente a atuação estadual depois de 2023? Não. Trata de competências expressas dos dois incisos; outras atribuições estaduais permanecem no regime pertinente.', 'Em 2026 ainda vale por padrão a transição até 31/12/2023? Não. O marco posterior é 1º/1/2024, sem perpetuar regra anterior nem ignorar texto atual dos artigos destinatários.', 'Transferência delimitada','Mudança de atribuições específicas, distinta de extinção total da competência de um ente.',notes=['Integrar arts. 21/24 atuais; não copiar antigo exercício que afirma inexistência de toda competência estadual após 2023.'])
add(339,'Questão histórica identifica autorização de crédito especial de R$ 264.954,00 para despesas de implantação do CTB. Resposta: verba específica, não repasse anual perpétuo.', 'Atualização do CTB não reabre automaticamente o crédito original nem prova sua execução orçamentária efetiva.', 'O artigo cria pagamento anual de R$ 264.954,00 para cada município? Não. Autoriza crédito especial específico à coordenação máxima para implantação, sem essa periodicidade ou rateio.', 'A autorização prova sozinha que todo valor foi efetivamente gasto? Não. Autorização e execução orçamentária são fatos distintos; o texto não certifica a despesa realizada.', 'Crédito de implantação','Autorização orçamentária específica histórica, distinta de receita permanente.',notes=['Não certificar eficácia orçamentária atual ou execução efetiva apenas pela preservação do texto compilado.'])
add(340,'Aluno separa data da lei original e início de vigência após 120 dias da publicação. Resposta: a lei não entrou em vigor instantaneamente só por ser assinada.', 'Leis modificadoras de 2020/2026 possuem próprias cláusulas de vigência; não copiar 120 dias automaticamente para cada alteração.', 'Toda alteração futura do CTB herda vacância de 120 dias? Não. O artigo rege o Código original; cada lei/ato modificador precisa de sua própria cláusula e data de publicação.', 'A data de conferência em 13/10/2026 é a data de vigência original? Não. Conferência editorial, data original e início de efeitos jurídicos são marcos distintos.', 'Vacância original','Intervalo até vigência do Código original, distinto das vacâncias de leis modificadoras.',notes=['Não contar vacância apenas da assinatura; texto fala data da PUBLICAÇÃO.'])
add(341,'Aluno consulta lei antiga 5.108/1966. Resposta: o art. 341 a incluiu no rol revogado; fonte histórica não deve alimentar exercício como regra atual.', 'Revogar artigos expressos de decreto-lei não significa revogar qualquer norma antiga não listada; examinar sucessão normativa concreta.', 'O rol permite apresentar antigo Código Nacional de Trânsito como vigente? Não. Ele está entre diplomas revogados; consulta histórica deve receber ressalva e contraste com o regime atual.', 'Revogação de arts. 1º–6º e 11 do decreto-lei citado equivale automaticamente a revogar todos seus artigos? Não. O texto diferencia artigos determinados e diplomas completos; não ampliar o rol sem análise.', 'Revogação expressa','Supressão dos diplomas/dispositivos indicados, distinta de certificação geral de toda norma histórica.',notes=['Não usar remissões históricas para restaurar regras revogadas ou presumir repristinação.'])
add('anexo-1','Carro fica imobilizado em sinal vermelho. Resposta: INTERRUPÇÃO DE MARCHA, não parada para embarque nem estacionamento. Ao deixar passageiro pelo tempo necessário, é PARADA.', 'Passar à frente em faixa distinta é PASSAGEM; ultrapassagem exige sair e retornar à faixa de origem. Carga/descarga não se torna parada só por ser rápida.', 'Ciclomotor exige simultaneamente motor a combustão de até 50 cm³ E motor elétrico de até 4 kW? Não. São alternativas de propulsão, com limites próprios, duas/três rodas e máximo de fabricação de 50 km/h.', 'Todo veículo no mesmo local sem se mover é estacionamento pelo anexo? Não. Há parada para passageiros, interrupção momentânea de marcha e estacionamento; finalidade e contexto importam.', 'Interrupção de marcha','Imobilização por circunstância momentânea do trânsito, distinta de parada/estacionamento.',simples='O Anexo I define agentes, veículos, vias, sinais e movimentos para aplicação do CTB. Estude por contrastes: parada de passageiros, estacionamento e interrupção de marcha; passagem e ultrapassagem; estrada não pavimentada e rodovia pavimentada; ciclofaixa delimitada e ciclovia fisicamente separada. Ciclomotor: duas/três rodas, motor a combustão até 50 cm³ OU elétrico até 4 kW, velocidade máxima de fabricação até 50 km/h. Para elétricos, integrar classificação específica da Resolução 996/2023. Definição antiga de PATRULHAMENTO está revogada; conceitos atuais próprios não devem ser confundidos.',pontos=['Automóvel: até OITO pessoas exclusive condutor; microônibus ATÉ VINTE; ônibus MAIS DE VINTE, mesmo adaptado para menos.','Caminhonete: carga PBT até 3.500 kg; camioneta: misto no mesmo compartimento; caminhão: PBT superior a 3.500 kg.','Parada: embarque/desembarque de passageiros pelo tempo necessário; interrupção: circunstância momentânea do trânsito; carga/descarga tem conceito próprio e regime do art. 47.','Passagem: faixas distintas; ultrapassagem: sair e retornar à faixa de origem, no mesmo sentido.','Bicicleta/ciclo de propulsão humana; bicicleta elétrica equiparada tem condições da Resolução 996, não todo elétrico é ciclomotor.','PBT: tara + lotação; capacidade máxima de tração não é sinônimo de PBT.','Veículo de coleção: MAIS de trinta anos, original OU modificado, com valor histórico próprio; idade sozinha não basta.','Sinistro: dano a veículo/carga e/ou lesões a pessoas/animais, podendo afetar via/meio ambiente; pelo menos uma parte em movimento no âmbito descrito.','Agente de trânsito civil efetivo de carreira e agente da autoridade de trânsito não são conceitos idênticos; designações/convênios dependem do recorte.','Patrulhamento ostensivo da PRF, policiamento ostensivo de trânsito da PM e patrulhamento viário têm atribuições próprias.'],atencao=['Conjunção OU para combustão/elétrico no ciclomotor; não ensinar 50 cm³ e 4 kW como requisitos simultâneos.','Definições devem ser integradas aos artigos e normas atuais: definição de pisca-alerta não elimina uso determinado por sinalização do art. 40.','Revogação de PATRULHAMENTO em 2023 não revogou todos os conceitos de patrulhamento/policiamento.','Veículo elétrico/híbrido integra definição de automotor; bonde sobre trilhos tem conceito distinto.','Revisão da unidade e de seus contrastes; não certifica todos os atos técnicos, sinais e anexos regulamentares externos.'],sources=[R996],termos=[dict(termo='Tara e PBT',significado='Tara é peso próprio com componentes descritos; PBT corresponde à tara mais lotação.'),dict(termo='Passagem e ultrapassagem',significado='Passagem em faixas distintas; ultrapassagem sai e retorna à faixa de origem.')])
assert len(rows)==48 and set(rows)==set(expected)
for key,row in rows.items():
 assert 'Variação:' in row['exemplo'] and len(row['prova'])==2,key
 assert all('?' in q and len(q.split('?',1)[1].strip())>45 for q in row['prova']),key
 assert row['termos'] and all(t['significado'] for t in row['termos'])
Path(sys.argv[2]).write_text(json.dumps({'course_slug':'transito','units':rows},ensure_ascii=False,indent=2)+'\n')
print('48 explicitly reviewed CTB units')
